import{_ as i,l as n,o as e,c as s,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"中断下半部","description":"","frontmatter":{"title":"中断下半部","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interrupt-bottom-half.md","filePath":"cs/interrupt-bottom-half.md","lastUpdated":1789023840000}'),E={name:"cs/interrupt-bottom-half.md"};function h(m,a,u,A,_,B){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="中断下半部" tabindex="-1">中断下半部 <a class="header-anchor" href="#中断下半部" aria-label="Permalink to &quot;中断下半部&quot;">​</a></h1><div class="epigraph"><p>中断处理应尽可能短：记下设备状态，把费时工作留到中断已重新开启之后。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Silberschatz et al. 对中断处理的整理</footer></div><p><a href="/cs/syscall-trace">上一课</a>让用户同步地请内核办事。设备却在 CPU 不知情时完成 DMA、网卡收包。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>已经能跳进处理程序。缺口是：若在关中断的上半部里做完协议解析与进程唤醒，延迟与死锁风险都不可接受。本课把工作拆成<strong>上半部与下半部</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上半部（ISR）发生时，可能关中断或关该 IRQ 线，不能睡眠，不能做无界循环。网卡却可能一次送来整页数据，需要分配、校验、交给等待 <code>read</code> 的线程。缺口不是新的陷入硬件，而是承认：入口只做<strong>不可延迟</strong>的最小动作（读状态、清设备、排队），其余放到可调度、可开中断的下半部。</p><p>本课不把 Linux <code>softirq</code>/<code>tasklet</code>/<code>workqueue</code> 的历史逐一对照，只保留「短上半、可推迟下半」这条纪律。</p><p><span class="marginnote">下半部仍在内核态，只是不再占用 IRQ 上下文。它可以唤醒阻塞在系统调用路径上的线程，于是用户 <code>read</code> 才返回。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设备中断 → 上半部：应答硬件、把缓冲区描述符或状态填进队列、标记「有下半部待跑」→ 尽快返回。之后在内核可抢占点或软中断点跑下半部：处理队列、调用协议、<code>wakeup</code>。若下半部仍太重，再丢给工作线程，完全像普通内核线程那样可睡眠。</p>',9)),(e(),l(p,null,{default:o(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%20IRQ%22%5D%20--%3E%20TOP%5B%22%E4%B8%8A%E5%8D%8A%E9%83%A8%3A%20%E6%B8%85%E8%AE%BE%E5%A4%87%E3%80%81%E5%85%A5%E9%98%9F%22%5D%0A%20%20TOP%20--%3E%20BH%5B%22%E4%B8%8B%E5%8D%8A%E9%83%A8%3A%20%E5%A4%84%E7%90%86%E3%80%81%E5%94%A4%E9%86%92%22%5D%0A%20%20BH%20--%3E%20SYS%5B%22%E9%98%BB%E5%A1%9E%E4%B8%AD%E7%9A%84%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与系统调用路径的会合点是等待队列：调用在路径里睡眠，下半部唤醒。本课不写具体队列 API。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拆分让中断延迟有上界：其他设备不会被一次长时间 ISR 饿死。上半部与下半部之间的队列是共享数据，后课的锁必须分清「能否在 IRQ 上下文拿」。本课只预告这个约束，不引入自旋锁。</p><p>DMA 完成中断是典型上半部来源；字节如何从设备进内存，是本课程更后的 <a href="/cs/io-dma">I/O 与 DMA</a>。这里只要求：完成通知走中断，重活不走 ISR。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲解线程化中断的全部实现，不把信号当成下半部——信号是用户态异步通知，更后一课。也不把「下半部」说成必须延迟例程这一种名字；教材与 Linux 用词不同，对象相同。</p><p>NMI 与机器检查几乎不能推迟，不属于普通下半部；主干只谈可屏蔽设备中断。</p><p>后课默认：设备完成先入上半部，再在下半部会合到阻塞的系统调用。CPU 上有多条可运行线程时如何选，下一课先问调度指标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上半部短、不可睡；下半部可推迟、可唤醒系统调用。</li><li>与用户路径通过等待队列会合。</li><li>锁与 IRQ 的搭配是后课；DMA 细节更后。</li><li>出处：Bovet and Cesati；Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',10))])}const S=i(E,[["render",h]]);export{b as __pageData,S as default};
